"""Lua diagnostics for the statically verified Locale/Achievements bindings.

The host may execute ``LOCALE_CASES`` one case at a time. Native localization
cases require the owner to bind an already initialized module first; these
scripts never load or initialize a DLL themselves.
"""
from civ6_host.runtime.provenance import historical_source_file as _historical_source_file, historical_module_file as _historical_module_file, worker_path as _worker_path, pin_key as _pin_key, installed_source_pins as _installed_source_pins
from civ6_host.runtime.resource_resolution import resolve_path as _resolve_resource_path
LOCALE_KEYS = ('Bundle', 'LookupBundle', 'GetLanguages', 'GetAudioLanguages', 'GetLanguageDisplayName', 'GetLanguageCoverage', 'IsValidKey', 'HasTextKey', 'Compose', 'Lookup', 'LookupLanguage', 'StartsWith', 'EndsWith', 'IsNilOrEmpty', 'IsNilOrWhitespace', 'Length', 'SubString', 'SplitString', 'StripTags', 'ToUpper', 'ToLower', 'ToNumber', 'ToPercent', 'ToRomanNumeral', 'ToSpellout', 'ToOrdinal', 'Compare', 'GetCurrentLanguage', 'IsASCII', 'IsUTF8')
ACHIEVEMENT_KEYS = ('IsAchievementUnlocked', 'GetStat', 'GetAchievementHash', 'GetAchievementName', 'GetAchievementDisplayName', 'GetAchievementDescription', 'GetAchievementData', 'DeleteAchievementData')
LOCALE_CASES = {'namespace_surface': "\n        assert type(Locale) == 'table'\n        local localeKeys = {\n          'Bundle','LookupBundle','GetLanguages','GetAudioLanguages','GetLanguageDisplayName',\n          'GetLanguageCoverage','IsValidKey','HasTextKey','Compose','Lookup','LookupLanguage',\n          'StartsWith','EndsWith','IsNilOrEmpty','IsNilOrWhitespace','Length','SubString',\n          'SplitString','StripTags','ToUpper','ToLower','ToNumber','ToPercent','ToRomanNumeral',\n          'ToSpellout','ToOrdinal','Compare','GetCurrentLanguage','IsASCII','IsUTF8'\n        }\n        for _, key in ipairs(localeKeys) do\n            assert type(Locale[key]) == 'function', 'missing Locale.' .. key\n        end\n        assert type(Achievements) == 'table'\n        local achievementKeys = {\n          'IsAchievementUnlocked','GetStat','GetAchievementHash','GetAchievementName',\n          'GetAchievementDisplayName','GetAchievementDescription','GetAchievementData',\n          'DeleteAchievementData'\n        }\n        for _, key in ipairs(achievementKeys) do\n            assert type(Achievements[key]) == 'function', 'missing Achievements.' .. key\n        end\n    ", 'starts_with': "\n        assert Locale.StartsWith('MapScript', 'Map') == true\n        assert Locale.StartsWith('MapScript', 'map') == false\n        assert Locale.StartsWith('', '') == true\n    ", 'localized_key_apis': "\n        local valid = Locale.IsValidKey('LOC_TYPE_TRAIT_HOUSING')\n        local present = Locale.HasTextKey('LOC_TYPE_TRAIT_HOUSING')\n        assert type(valid) == 'boolean' and type(present) == 'boolean'\n    ", 'lookup_without_format_arguments': "\n        local value = Locale.Lookup('LOC_TYPE_TRAIT_HOUSING')\n        assert type(value) == 'string'\n    ", 'lookup_string_argument': "\n        local value = Locale.Lookup('LOC_GRAMMAR_A_AN', 'Warrior')\n        assert type(value) == 'string'\n    ", 'lookup_nonstring_argument_refusal': "\n        local ok, message = pcall(Locale.Lookup, 'LOC_GRAMMAR_A_AN', {})\n        assert not ok and string.find(message, 'accepts only string format arguments', 1, true)\n    ", 'achievement_refusal_is_explicit': "\n        local ok, message = pcall(Achievements.IsAchievementUnlocked, 'anything')\n        assert not ok and string.find(message, 'Achievements diagnostic explicitly refuses', 1, true)\n    "}
